using Microsoft.Extensions.AI;
using Microsoft.Extensions.AI.Evaluation;
using Microsoft.Extensions.AI.Evaluation.Quality;
using Microsoft.Extensions.AI.Evaluation.Reporting;
using Microsoft.VisualStudio.TestTools.UnitTesting;

namespace MyApp.Evals;

[TestClass]
public class ChatEvals
{
    private static ReportingConfiguration? s_reportingConfiguration;

    private static ReportingConfiguration ReportingConfiguration =>
        s_reportingConfiguration ??= CreateReportingConfiguration();

    private static ReportingConfiguration CreateReportingConfiguration()
    {
        var endpoint = Environment.GetEnvironmentVariable("AZURE_OPENAI_ENDPOINT")
            ?? throw new InvalidOperationException("AZURE_OPENAI_ENDPOINT is not set.");
        var deploymentName = Environment.GetEnvironmentVariable("AZURE_OPENAI_DEPLOYMENT") ?? "gpt-4o-mini";

        var chatClient = new Azure.AI.Inference.ChatCompletionsClient(
            new Uri(endpoint),
            new Azure.AzureKeyCredential(
                Environment.GetEnvironmentVariable("AZURE_OPENAI_API_KEY") ?? string.Empty));

        IChatClient evaluator = chatClient.AsChatClient(deploymentName);

        var evaluators = new IEvaluator[]
        {
            new CoherenceEvaluator(),
            new RelevanceEvaluator(),
            new FluencyEvaluator(),
            new GroundednessEvaluator(),
        };

        return new ReportingConfiguration(
            storageRootPath: Path.Combine(Directory.GetCurrentDirectory(), "eval-results"),
            evaluators: evaluators,
            chatConfiguration: new ChatConfiguration(evaluator));
    }

    [TestMethod]
    public async Task Chat_responds_coherently_to_greeting()
    {
        await using var scenario = await ReportingConfiguration.CreateScenarioRunAsync(
            scenarioName: nameof(Chat_responds_coherently_to_greeting));

        var messages = new List<ChatMessage>
        {
            new(ChatRole.User, "Hello, how can you help me today?")
        };

        var response = new ChatMessage(ChatRole.Assistant,
            "Hello! I'm here to help you with any questions or tasks you may have. How can I assist you?");

        await scenario.EvaluateAsync(messages, response);

        scenario.AssertAllNumericMetricsAreAbove(3.0f);
    }

    [TestMethod]
    public async Task Chat_responds_relevantly_to_question()
    {
        await using var scenario = await ReportingConfiguration.CreateScenarioRunAsync(
            scenarioName: nameof(Chat_responds_relevantly_to_question));

        var messages = new List<ChatMessage>
        {
            new(ChatRole.User, "What is the capital of France?")
        };

        var response = new ChatMessage(ChatRole.Assistant,
            "The capital of France is Paris. It is the largest city in France and serves as the country's political, economic, and cultural center.");

        await scenario.EvaluateAsync(messages, response);

        scenario.AssertAllNumericMetricsAreAbove(3.0f);
    }

    [TestMethod]
    public async Task Chat_response_is_grounded_in_context()
    {
        await using var scenario = await ReportingConfiguration.CreateScenarioRunAsync(
            scenarioName: nameof(Chat_response_is_grounded_in_context));

        var messages = new List<ChatMessage>
        {
            new(ChatRole.System, "You are a helpful assistant. Use the following context to answer: The store is open Monday through Friday from 9am to 5pm."),
            new(ChatRole.User, "When is the store open?")
        };

        var response = new ChatMessage(ChatRole.Assistant,
            "The store is open Monday through Friday from 9am to 5pm.");

        await scenario.EvaluateAsync(messages, response);

        scenario.AssertAllNumericMetricsAreAbove(3.0f);
    }
}

